'.hm-down .a-CardView-title{color:#b91c1c}.hm-open .a-CardView-title{color:#7c3aed}',
'.hm-status{display:inline-block;padding:.1rem .55rem;border-radius:999px;font-weight:600;font-size:.75rem;color:#fff}',
'.hm-status--UP{background:#15803d}.hm-status--DEGRADED{background:#d97706}',
'.hm-status--DOWN{background:#b91c1c}.hm-status--PENDING{background:#6b7280}',
'.hm-status--OPEN{background:#b91c1c}.hm-status--RESOLVED{background:#15803d}',
'.a-CardView-badge.u-success{background:#15803d!important;color:#fff!important}',
'.a-CardView-badge.u-warning{background:#d97706!important;color:#fff!important}',
'.a-CardView-badge.u-danger{background:#b91c1c!important;color:#fff!important}',
'.a-CardView-mainContent{word-break:break-word}',
'@media (max-width:640px){.a-CardView-items--grid3col,.a-CardView-items--grid4col{grid-template-columns:1fr 1fr!important}.hm-targets .a-CardView-items{grid-template-columns:1fr!important}}'))
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(1014)
,p_plug_name=>'Summary'
,p_static_id=>'summary'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>2074200852440250129
,p_plug_display_sequence=>10
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select to_char(count(case when status = ''UP'' then 1 end)) as title, ''Up'' as subtitle, ''hm-up'' as css, 1 as seq from hm_target_status_v where enabled_yn = ''Y''',
'union all',
'select to_char(count(case when status = ''DEGRADED'' then 1 end)), ''Degraded'', ''hm-degraded'', 2 from hm_target_status_v where enabled_yn = ''Y''',
'union all',
'select to_char(count(case when status = ''DOWN'' then 1 end)), ''Down'', ''hm-down'', 3 from hm_target_status_v where enabled_yn = ''Y''',
'union all',
'select to_char(count(*)), ''Open incidents'', ''hm-open'', 4 from hm_incidents where resolved_at is null',
'order by 4'))
,p_plug_source_type=>'NATIVE_CARDS'
,p_region_css_classes=>'hm-kpi'
,p_lazy_loading=>false
,p_plug_query_num_rows_type=>'SCROLL'
,p_show_total_row_count=>false
);
wwv_flow_imp_page.create_card(
 p_id=>wwv_flow_imp.id(1018)
,p_region_id=>wwv_flow_imp.id(1014)
