,p_plug_name=>'Current status'
,p_static_id=>'current-status'
,p_region_template_options=>'#DEFAULT#:t-Region--noBorder:t-Region--hiddenOverflow'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>20
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select target_id,',
'       name as title,',
'       case target_type when ''HTTP'' then ''HTTPS'' else ''SQL'' end',
'         || '' - every '' || interval_min || '' min''',
'         || case when last_checked_at is not null',
'                 then '' - checked '' || to_char(last_checked_at at time zone ''Africa/Johannesburg'', ''DD Mon HH24:MI'') || '' SAST'' end as subtitle,',
'       nvl(message, ''Not checked yet'') as body,',
'       ''Uptime 24h: '' || nvl(to_char(uptime_24h, ''fm990.00'') || ''%'', ''-'')',
'         || ''  |  Avg '' || nvl(to_char(avg_ms_24h) || '' ms'', ''-'') as second_body,',
'       status as badge,',
'       status_css,',
'       status_icon',
'  from hm_target_status_v',
' where enabled_yn = ''Y''',
' order by decode(status, ''DOWN'', 1, ''DEGRADED'', 2, ''PENDING'', 3, 4), name'))
