,p_seq=>10
,p_name=>'Response ms'
,p_data_source_type=>'SQL'
,p_data_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select t.name as series,',
'       to_char(trunc(cast(c.checked_at at time zone ''Africa/Johannesburg'' as date), ''HH24'')',
'               + floor(to_number(to_char(cast(c.checked_at at time zone ''Africa/Johannesburg'' as date), ''MI'')) / 15) * 15 / 1440,',
