wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(1063)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Load target'
,p_static_id=>'load-target'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'for r in (select * from hm_targets where target_id = :P3_TARGET_ID) loop',
'  :P3_NAME            := r.name;',
'  :P3_TARGET_TYPE     := r.target_type;',
'  :P3_ENDPOINT        := r.endpoint;',
'  :P3_EXPECTED_STATUS := r.expected_status;',
'  :P3_WARN_THRESHOLD  := r.warn_threshold;',
'  :P3_CRIT_THRESHOLD  := r.crit_threshold;',
'  :P3_TIMEOUT_SEC     := r.timeout_sec;',
'  :P3_INTERVAL_MIN    := r.interval_min;',
'  :P3_ENABLED_YN      := r.enabled_yn;',
'  :P3_DESCRIPTION     := r.description;',
'end loop;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'P3_TARGET_ID'
,p_process_when_type=>'ITEM_IS_NOT_NULL'
,p_internal_uid=>1063
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(1064)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Save target'
,p_static_id=>'save-target'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'if :P3_TARGET_ID is null then',
'  insert into hm_targets (name, target_type, endpoint, expected_status, warn_threshold, crit_threshold,',
'                          timeout_sec, interval_min, enabled_yn, description)',
'  values (:P3_NAME, :P3_TARGET_TYPE, :P3_ENDPOINT, :P3_EXPECTED_STATUS, :P3_WARN_THRESHOLD, :P3_CRIT_THRESHOLD,',
'          :P3_TIMEOUT_SEC, :P3_INTERVAL_MIN, nvl(:P3_ENABLED_YN, ''N''), :P3_DESCRIPTION)',
'  returning target_id into :P3_TARGET_ID;',
'else',
'  update hm_targets',
'     set name = :P3_NAME, target_type = :P3_TARGET_TYPE, endpoint = :P3_ENDPOINT,',
'         expected_status = :P3_EXPECTED_STATUS, warn_threshold = :P3_WARN_THRESHOLD,',
'         crit_threshold = :P3_CRIT_THRESHOLD, timeout_sec = :P3_TIMEOUT_SEC,',
'         interval_min = :P3_INTERVAL_MIN, enabled_yn = nvl(:P3_ENABLED_YN, ''N''),',
'         description = :P3_DESCRIPTION, updated_on = systimestamp, updated_by = :APP_USER',
'   where target_id = :P3_TARGET_ID;',
'end if;',
'if :REQUEST = ''CHECK_NOW'' then',
'  hm_pkg.check_target(to_number(:P3_TARGET_ID));',
'end if;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_success_message=>'Target saved.'
,p_process_when=>'SAVE,CHECK_NOW'
,p_process_when_type=>'REQUEST_IN_CONDITION'
,p_internal_uid=>1064
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(1065)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Delete target'
,p_static_id=>'delete-target'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'delete from hm_targets where target_id = :P3_TARGET_ID;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(1059)
,p_process_success_message=>'Target deleted.'
,p_internal_uid=>1065
);
wwv_flow_imp_page.create_page_branch(
 p_id=>wwv_flow_imp.id(1066)
,p_branch_name=>'Back to targets'
,p_branch_action=>'f?p=&APP_ID.:2:&SESSION.::&DEBUG.:::&success_msg=#SUCCESS_MSG#'
,p_branch_point=>'AFTER_PROCESSING'
,p_branch_type=>'REDIRECT_URL'
,p_branch_sequence=>10
);
end;
